// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // initial owner is address(0); it transfers ownership to the fuzzed address
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        // the designated owner must be able to call owned() without reverting
        vm.prank(newOwner);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
